import os, tempfile, wave
from pathlib import Path
from fastcore.utils import *

# %% ../nbs/05_voice.ipynb #c007
STT_SP = 'You transcribe speech exactly. Keep technical terms, Sanskrit words (in IAST) and maths as spoken. Reply with the transcript only.'
DFLT_GEMMA = 'litert-community/gemma-4-E4B-it-litert-lm'
DFLT_WHISPER = 'mlx-community/whisper-large-v3-turbo-asr-fp16'
DFLT_PARAKEET = 'mlx-community/parakeet-tdt-0.6b-v3'

# %% ../nbs/05_voice.ipynb #c009
def _gemma(path, hint=''):
    from rishi import Chat, resp_text
    chat = Chat(os.getenv('ABHYASA_GEMMA', DFLT_GEMMA), sp=STT_SP)
    try: return resp_text(chat([f'Transcribe this clip.{" Words it may use: " + hint if hint else ""}', Path(path)]))
    finally: chat.close()

_mlx = {}
def _mlx_model(nm):
    "An mlx-audio speech model, loaded once."
    from mlx_audio.stt.utils import load
    if nm not in _mlx: _mlx[nm] = load(nm)
    return _mlx[nm]

def _mlx_whisper(path, hint=''):
    return _mlx_model(os.getenv('ABHYASA_WHISPER', DFLT_WHISPER)).generate(str(path), initial_prompt=hint or None).text

def _parakeet(path, hint=''): return _mlx_model(DFLT_PARAKEET).generate(str(path)).text

ENGINES = dict(gemma=_gemma, whisper=_mlx_whisper, parakeet=_parakeet)

# %% ../nbs/05_voice.ipynb #c011
def transcribe(audio, engine:str=None, hint:str='') -> str:
    "Text for a WAV file or WAV bytes. `hint` lists words that the speaker can use, such as the name of the concept."
    eng = ENGINES[engine or os.getenv('ABHYASA_STT', 'gemma')]
    if isinstance(audio, (bytes, bytearray)):
        with tempfile.NamedTemporaryFile(suffix='.wav', delete=False) as f: f.write(audio)
        try: return eng(f.name, hint).strip()
        finally: os.unlink(f.name)
    return eng(audio, hint).strip()

# %% ../nbs/05_voice.ipynb #c013
def wav_seconds(audio:bytes) -> float:
    "The length of WAV bytes, in seconds; 0 when they are not WAV."
    import io
    try:
        with wave.open(io.BytesIO(audio)) as w: return w.getnframes() / w.getframerate()
    except Exception: return 0.
